// The two generators behind gen-api.mjs and gen-mocks.mjs, as functions so the Vitest suite can
// run them in memory and compare with the committed files.
import openapiTS, { astToString } from "openapi-typescript";
import { bundle, createConfig } from "@redocly/openapi-core";
import { pathToFileURL } from "node:url";
import { openapiYaml } from "./paths.mjs";

const header = [
  "// Generated by scripts/gen-api.mjs from docs/api/openapi.yaml with openapi-typescript. Do not edit.",
  "// Regenerate with `npm run gen:api`; CI fails when this file is out of date.",
  "",
].join("\n");

/** The text of src/api/schema.d.ts. */
export async function generateApiTypes() {
  const ast = await openapiTS(pathToFileURL(openapiYaml), {
    alphabetize: false,
    exportType: false,
    defaultNonNullable: false,
  });
  return header + astToString(ast);
}

/** The text of src/mocks/openapi.json: the contract with its external refs bundled in. */
export async function generateMockDocument() {
  const config = await createConfig({});
  const result = await bundle({ ref: openapiYaml, config, dereference: false });
  const errors = result.problems.filter((p) => p.severity === "error");
  if (errors.length > 0) {
    throw new Error("Bundling docs/api/openapi.yaml failed:\n" + errors.map((p) => p.message).join("\n"));
  }
  return JSON.stringify(result.bundle.parsed, null, 2) + "\n";
}
